import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { createManifest, verifyManifest } from '../snapshot.js';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-drift-'));
  t.after(() => fs.rmSync(root, {recursive:true, force:true}));
  return root;
}
function put(root, name, bytes = 'abc') {
  fs.mkdirSync(path.dirname(path.join(root, name)), {recursive:true});
  fs.writeFileSync(path.join(root, name), bytes);
  fs.chmodSync(path.join(root, name), 0o640);
}
function cli(args, status, expected) {
  const result = spawnSync(process.execPath, [script, ...args], {encoding:'utf8'});
  assert.ifError(result.error);
  assert.equal(result.status, status, result.stderr);
  if (status === 2) {
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.trim());
  } else {
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify(expected) + '\n');
  }
}

test('sorted drift categories, reasons, unusual names and immutable inputs', t => {
  const root = fixture(t);
  const names = ['z', 'ä', 'A', 'space tab\tline\n雪', 'mode', 'both', 'gone/file', 'link/file', 'blocked/file', 'directory'];
  for (const name of names) put(root, name, Buffer.from([0, 255, 10]));
  const selections = Object.freeze([...names]);
  const manifest = createManifest(root, selections);
  assert.deepEqual(manifest.files.map(e => e.path), [...names].sort());
  manifest.files.reverse();
  for (const entry of manifest.files) Object.freeze(entry);
  Object.freeze(manifest.files);
  Object.freeze(manifest);
  const before = JSON.stringify(manifest);
  fs.writeFileSync(path.join(root, 'z'), 'new');
  fs.chmodSync(path.join(root, 'mode'), 0o600);
  fs.writeFileSync(path.join(root, 'both'), 'different size');
  fs.chmodSync(path.join(root, 'both'), 0o700);
  fs.rmSync(path.join(root, 'gone'), {recursive:true});
  fs.rmSync(path.join(root, 'link'), {recursive:true});
  fs.symlinkSync(root, path.join(root, 'link'));
  fs.rmSync(path.join(root, 'blocked'), {recursive:true});
  put(root, 'blocked');
  fs.unlinkSync(path.join(root, 'directory'));
  fs.mkdirSync(path.join(root, 'directory'));
  put(root, 'unselected');
  assert.deepEqual(verifyManifest(root, manifest), {
    ok:false,
    unchanged:['A', 'space tab\tline\n雪', 'ä'],
    changed:[{path:'both', reasons:['content', 'mode']}, {path:'mode', reasons:['mode']}, {path:'z', reasons:['content']}],
    missing:['gone/file'], unsafe:['blocked/file', 'directory', 'link/file'],
  });
  assert.equal(JSON.stringify(manifest), before);
  assert.deepEqual(selections, names);
});

test('complete validation, safe integer boundary, unknown fields and size-only drift', t => {
  const root = fixture(t);
  put(root, 'file');
  const entry = createManifest(root, ['file']).files[0];
  const wrap = e => ({version:1, files:[e]});
  for (const size of [Number.MAX_SAFE_INTEGER, 0, 4]) {
    assert.deepEqual(verifyManifest(root, wrap({...entry, size})).changed, [{path:'file', reasons:['content']}]);
  }
  const invalid = [null, [], {}, {version:2, files:[]}, {version:1, files:{}},
    {version:1, files:[entry, entry]}, {version:1, files:[null]}, {version:1, files:[[]]}];
  for (const size of [-1, 1.5, NaN, Infinity, '3', Number.MAX_SAFE_INTEGER + 1, Number.MAX_SAFE_INTEGER + 2]) invalid.push(wrap({...entry, size}));
  for (const mode of [-1, 512, 0.5, NaN, '416']) invalid.push(wrap({...entry, mode}));
  for (const sha256 of ['A'.repeat(64), '0'.repeat(63), '0'.repeat(65), '0'.repeat(64) + '\n', null]) invalid.push(wrap({...entry, sha256}));
  for (const selected of ['', '/file', 'a\\b', 'a\0b', 'a//b', 'a/', './file', 'a/../file', 'a/./b', 3]) {
    invalid.push(wrap({...entry, path:selected}));
    assert.throws(() => createManifest(root, [selected]), Error);
  }
  for (const manifest of invalid) assert.throws(() => verifyManifest(root, manifest), Error);
  assert.throws(() => verifyManifest(root, {version:1, files:[{...entry, path:'missing'}, {...entry, mode:512}]}), Error);
  assert.equal(verifyManifest(root, {version:1, extra:true, files:[{...entry, ignored:123}]}).ok, true);
  for (const mode of [0, 511]) assert.doesNotThrow(() => verifyManifest(root, wrap({...entry, mode})));
  assert.deepEqual(verifyManifest(root, {version:1, files:[]}), {ok:true, unchanged:[], changed:[], missing:[], unsafe:[]});
  assert.throws(() => createManifest(root, ['file', 'file']), Error);
  assert.throws(() => createManifest(root, 'file'), Error);
});

test('roots, final symlinks and unsafe selections', t => {
  const root = fixture(t);
  put(root, 'file');
  fs.symlinkSync('file', path.join(root, 'sym'));
  fs.symlinkSync('absent', path.join(root, 'dangling'));
  fs.symlinkSync(root, path.join(root, 'root-link'));
  const entry = createManifest(root, ['file']).files[0];
  for (const selected of ['sym', 'dangling', 'file/child', 'root-link/file']) {
    assert.throws(() => createManifest(root, [selected]), Error);
    assert.deepEqual(verifyManifest(root, {version:1, files:[{...entry, path:selected}]}).unsafe, [selected]);
  }
  for (const badRoot of [path.join(root, 'absent'), path.join(root, 'file'), path.join(root, 'root-link'), path.join(root, 'root-link') + '/']) {
    assert.throws(() => createManifest(badRoot, []), Error);
    assert.throws(() => verifyManifest(badRoot, {version:1, files:[]}), Error);
  }
  assert.throws(() => createManifest(root, ['absent']), Error);
});

test('CLI stdout, stderr, exit statuses and import isolation', t => {
  const root = fixture(t);
  put(root, 'file');
  const manifest = createManifest(root, ['file']);
  const manifestFile = path.join(root, 'manifest.json');
  fs.writeFileSync(manifestFile, JSON.stringify(manifest));
  cli(['create', root, 'file'], 0, manifest);
  cli(['create', root], 0, {version:1, files:[]});
  cli(['verify', root, manifestFile], 0, verifyManifest(root, manifest));
  put(root, 'file', 'drift');
  cli(['verify', root, manifestFile], 1, verifyManifest(root, manifest));
  for (const args of [[], ['unknown'], ['create'], ['verify'], ['verify', root], ['verify', root, manifestFile, 'extra'], ['create', root, '../bad'], ['create', root, 'missing'], ['create', root, 'file', 'file'], ['create', path.join(root, 'missing')], ['verify', root, path.join(root, 'missing')], ['verify', root, root]]) cli(args, 2);
  fs.writeFileSync(manifestFile, '{');
  cli(['verify', root, manifestFile], 2);
  fs.writeFileSync(manifestFile, '{"version":1,"files":[{}]}');
  cli(['verify', root, manifestFile], 2);
  fs.writeFileSync(manifestFile, JSON.stringify(manifest));
  cli(['verify', path.join(root, 'missing'), manifestFile], 2);
  const imported = spawnSync(process.execPath, ['--input-type=module', '-e', `import ${JSON.stringify(new URL('../snapshot.js', import.meta.url).href)}`], {encoding:'utf8'});
  assert.ifError(imported.error);
  assert.equal(imported.status, 0);
  assert.equal(imported.stdout, '');
  assert.equal(imported.stderr, '');
});

