import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { createManifest, verifyManifest } from '../snapshot.js';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-drift-'));
  t.after(() => fs.rmSync(root, {recursive:true, force:true}));
  return root;
}
function put(root, name, bytes = 'abc') {
  fs.mkdirSync(path.dirname(path.join(root, name)), {recursive:true});
  fs.writeFileSync(path.join(root, name), bytes);
  fs.chmodSync(path.join(root, name), 0o640);
}
function cli(args, status, expected) {
  const result = spawnSync(process.execPath, [script, ...args], {encoding:'utf8'});
  assert.ifError(result.error);
  assert.equal(result.status, status, result.stderr);
  if (status === 2) {
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.trim());
  } else {
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify(expected) + '\n');
  }
}

test('sorted drift categories, reasons, unusual names and immutable inputs', t => {
  const root = fixture(t);
  const names = ['z', 'ä', 'A', 'space tab\tline\n雪', 'mode', 'both', 'gone/file', 'link/file', 'blocked/file', 'directory'];
  for (const name of names) put(root, name, Buffer.from([0, 255, 10]));
  const selections = Object.freeze([...names]);
  const manifest = createManifest(root, selections);
  assert.deepEqual(manifest.files.map(e => e.path), [...names].sort());
  manifest.files.reverse();
  for (const entry of manifest.files) Object.freeze(entry);
  Object.freeze(manifest.files);
  Object.freeze(manifest);
  const before = JSON.stringify(manifest);
  fs.writeFileSync(path.join(root, 'z'), 'new');
  fs.chmodSync(path.join(root, 'mode'), 0o600);
  fs.writeFileSync(path.join(root, 'both'), 'different size');
  fs.chmodSync(path.join(root, 'both'), 0o700);
  fs.rmSync(path.join(root, 'gone'), {recursive:true});
  fs.rmSync(path.join(root, 'link'), {recursive:true});
  fs.symlinkSync(root, path.join(root, 'link'));
  fs.rmSync(path.join(root, 'blocked'), {recursive:true});
  put(root, 'blocked');
  fs.unlinkSync(path.join(root, 'directory'));
  fs.mkdirSync(path.join(root, 'directory'));
  put(root, 'unselected');
  assert.deepEqual(verifyManifest(root, manifest), {
    ok:false,
    unchanged:['A', 'space tab\tline\n雪', 'ä'],
    changed:[{path:'both', reasons:['content', 'mode']}, {path:'mode', reasons:['mode']}, {path:'z', reasons:['content']}],
    missing:['gone/file'], unsafe:['blocked/file', 'directory', 'link/file'],
  });
  assert.equal(JSON.stringify(manifest), before);
  assert.deepEqual(selections, names);
});

test('complete validation, safe integer boundary, unknown fields and size-only drift', t => {
  const root = fixture(t);
  put(root, 'file');
  const entry = createManifest(root, ['file']).files[0];
  const wrap = e => ({version:1, files:[e]});
  for (const size of [Number.MAX_SAFE_INTEGER, 0, 4]) {
    assert.deepEqual(verifyManifest(root, wrap({...entry, size})).changed, [{path:'file', reasons:['content']}]);
  }
  const invalid = [null, [], {}, {version:2, files:[]}, {version:1, files:{}},
    {version:1, files:[entry, entry]}, {version:1, files:[null]}, {version:1, files:[[]]}];
  for (const size of [-1, 1.5, NaN, Infinity, '3', Number.MAX_SAFE_INTEGER + 1, Number.MAX_SAFE_INTEGER + 2]) invalid.push(wrap({...entry, size}));
